mapper.update:
update dc_member
set m_passwd=#{m_passwd}, m_tel=#{m_tel}, m_addr=#{m_addr},
m_addr_detail=#{m_addr_detail}, m_zipno=#{m_zipno}, m_email=#{m_email},
m_introduce=#{m_introduce}, m_birth=#{m_birth}, m_sns=#{m_sns}, m_img=#{m_img,jdbcType=VARCHAR}
where m_id=#{m_id}

update dc_member
set m_introduce=#{m_introduce}, m_authority=#{m_authority}, m_img=#{m_img,jdbcType=VARCHAR}, m_cre_sub=#{m_cre_sub,jdbcType=VARCHAR}
where m_id=#{m_id}

update dc_member
set m_cre_sub = 'P'
where m_id = #{m_id}
